<?php
require __DIR__.'/../src/bootstrap.php';
$error=null;$me=user();$setup=(int)query('SELECT COUNT(*) FROM users')->fetchColumn()===0;
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
 if(!hash_equals(csrf(),(string)($_POST['csrf']??'')))throw new RuntimeException('Skjemaet utløp. Last siden på nytt.');
 $action=$_POST['action']??'';
 if($action==='setup'&&$setup){
 if(mb_strlen(trim($_POST['name']??''))<2||!filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL)||strlen($_POST['password']??'')<12)throw new RuntimeException('Bruk navn, gyldig e-post og et passord med minst 12 tegn.');
 $db->beginTransaction();if(query('SELECT COUNT(*) FROM users')->fetchColumn())throw new RuntimeException('Butikken er allerede opprettet.');
 query('INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)',[trim($_POST['name']),mb_strtolower(trim($_POST['email'])),password_hash($_POST['password'],PASSWORD_DEFAULT),'admin']);$id=$db->lastInsertId();query('INSERT INTO racks(name) VALUES(?)',['Stativ 01']);$db->commit();session_regenerate_id(true);$_SESSION['uid']=(int)$id;go('/');
 }
 if($action==='register'){
 if($setup)throw new RuntimeException('Butikken må opprettes av eieren først.');
 if($me)throw new RuntimeException('Logg ut før du oppretter en ny bruker.');
 $name=trim($_POST['name']??'');$email=mb_strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';
 if(mb_strlen($name)<2||mb_strlen($name)>100||strlen($email)>254||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Oppgi navn (2–100 tegn) og en gyldig e-postadresse.');
 if(strlen($password)<12||strlen($password)>72)throw new RuntimeException('Passordet må være mellom 12 og 72 byte.');
 if($password!==($_POST['password_confirm']??''))throw new RuntimeException('Passordene er ikke like.');
 query('INSERT INTO users(name,email,password,role,share) VALUES(?,?,?,?,80)',[$name,$email,password_hash($password,PASSWORD_DEFAULT),'seller']);
 $id=(int)$db->lastInsertId();session_regenerate_id(true);$_SESSION['uid']=$id;unset($_SESSION['csrf']);go('/');
 }
 if($action==='login'){
 if(($_SESSION['login_after']??0)>time())throw new RuntimeException('Vent litt før du prøver igjen.');
 $u=query('SELECT * FROM users WHERE email=?',[mb_strtolower(trim($_POST['email']??''))])->fetch();
 if(!$u||!password_verify($_POST['password']??'',$u['password'])){$_SESSION['login_after']=time()+2;throw new RuntimeException('Feil e-post eller passord.');}
 session_regenerate_id(true);$_SESSION['uid']=$u['id'];unset($_SESSION['login_after']);go('/');
 }
 if(!$me)throw new RuntimeException('Du må logge inn.');
 if($action==='logout'){$_SESSION=[];session_destroy();go('/');}
 if($action==='seller'){admin();$share=filter_var($_POST['share']??'',FILTER_VALIDATE_INT);if($share===false||$share<0||$share>100||!filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL)||strlen($_POST['password']??'')<12||trim($_POST['name']??'')==='')throw new RuntimeException('Kontroller navn, e-post, prosent (0–100) og passord (minst 12 tegn).');query('INSERT INTO users(name,email,password,role,share) VALUES(?,?,?,?,?)',[trim($_POST['name']),mb_strtolower(trim($_POST['email'])),password_hash($_POST['password'],PASSWORD_DEFAULT),'seller',$share]);}
 if($action==='rack'){admin();$name=trim($_POST['name']??'');if($name==='')throw new RuntimeException('Gi stativet et navn.');query('INSERT INTO racks(name) VALUES(?)',[$name]);}
 if($action==='item'){$seller=$me['role']==='admin'?(int)($_POST['seller_id']??0):$me['id'];if(!query('SELECT id FROM users WHERE id=?',[$seller])->fetch()||!query('SELECT id FROM racks WHERE id=?',[(int)($_POST['rack_id']??0)])->fetch()||trim($_POST['name']??'')==='')throw new RuntimeException('Velg eier, stativ og navn på plagget.');$price=cents($_POST['price']??'');$photo=upload();query('INSERT INTO items(seller_id,rack_id,name,size,price,photo) VALUES(?,?,?,?,?,?)',[$seller,(int)$_POST['rack_id'],trim($_POST['name']),trim($_POST['size']??''),$price,$photo]);go('/?item='.$db->lastInsertId());}
 if($action==='sell'){admin();$db->exec('BEGIN IMMEDIATE');$item=query('SELECT i.*,u.share FROM items i JOIN users u ON u.id=i.seller_id WHERE i.id=?',[(int)($_POST['item_id']??0)])->fetch();if(!$item)throw new RuntimeException('Fant ikke plagget.');if(query('SELECT id FROM sales WHERE item_id=?',[$item['id']])->fetch())throw new RuntimeException('Plagget er allerede solgt.');$part=(int)round($item['price']*$item['share']/100);query('INSERT INTO sales(item_id,seller_amount,shop_amount,sold_by) VALUES(?,?,?,?)',[$item['id'],$part,$item['price']-$part,$me['id']]);$db->exec('COMMIT');go('/?item='.$item['id']);}
 if($action==='payout'){admin();$sid=(int)($_POST['seller_id']??0);$db->exec('BEGIN IMMEDIATE');$amount=(int)query('SELECT COALESCE(SUM(s.seller_amount),0) FROM sales s JOIN items i ON i.id=s.item_id WHERE i.seller_id=? AND s.payout_id IS NULL',[$sid])->fetchColumn();if($amount<=0)throw new RuntimeException('Ingen utestående beløp.');query('INSERT INTO payouts(seller_id,amount) VALUES(?,?)',[$sid,$amount]);$pid=$db->lastInsertId();query('UPDATE sales SET payout_id=? WHERE payout_id IS NULL AND item_id IN(SELECT id FROM items WHERE seller_id=?)',[$pid,$sid]);$db->exec('COMMIT');$_SESSION['flash']='Utbetaling registrert. Overfør beløpet via bank eller Vipps separat.';}
 go('/?page='.urlencode($_POST['return']??'inventory'));
 }catch(Throwable $ex){if($db->inTransaction())$db->rollBack();else {try{$db->exec('ROLLBACK');}catch(Throwable){}}$error=$ex instanceof PDOException?'Kunne ikke lagre. E-posten eller stativnavnet kan være i bruk.':$ex->getMessage();}
}
$me=user();
if(isset($_GET['photo'])){if(!$me){http_response_code(403);exit;}$i=query('SELECT * FROM items WHERE id=?',[(int)$_GET['photo']])->fetch();if(!$i||!$i['photo']||($me['role']!=='admin'&&$i['seller_id']!==$me['id'])){http_response_code(404);exit;}$path=ROOT.'/var/uploads/'.$i['photo'];header('Content-Type: '.(new finfo(FILEINFO_MIME_TYPE))->file($path));header('X-Content-Type-Options: nosniff');header('Cache-Control: private, max-age=3600');readfile($path);exit;}
$page=$_GET['page']??'inventory';$isAdmin=($me['role']??'')==='admin';
function field(string $label,string $name,string $type='text',string $extra=''):void{echo '<label>'.e($label).'<input name="'.e($name).'" type="'.e($type).'" '.$extra.' required></label>';}
function action(string $name):void{echo token().'<input type="hidden" name="action" value="'.e($name).'">';}
