$stats=query("SELECT COUNT(*) total,COALESCE(SUM(CASE WHEN s.id IS NULL THEN 1 ELSE 0 END),0) available,COALESCE(SUM(s.seller_amount+s.shop_amount),0) sold,COALESCE(SUM(CASE WHEN s.payout_id IS NULL THEN s.seller_amount ELSE 0 END),0) pending FROM items i LEFT JOIN sales s ON s.item_id=i.id WHERE $filter")->fetch();
