<?php if(isset($_GET['item'])):
$item=query("SELECT i.*,u.name seller,r.name rack,s.id sale,s.created_at sold_at FROM items i JOIN users u ON u.id=i.seller_id JOIN racks r ON r.id=i.rack_id LEFT JOIN sales s ON s.item_id=i.id WHERE i.id=? AND $filter",[(int)$_GET['item']])->fetch();if(!$item):?><h1>Fant ikke plagget</h1><?php else: $code='SOLA-'.str_pad((string)$item['id'],6,'0',STR_PAD_LEFT);?><div class="heading"><div><p class="eyebrow"><?=e($code)?></p><h1><?=e($item['name'])?></h1></div><button class="secondary" onclick="window.print()">Skriv ut etikett</button></div><section class="detail"><div class="item-photo"><?php if($item['photo']):?><img src="/?photo=<?=$item['id']?>" alt="<?=e($item['name'])?>"><?php else:?><span>Foto mangler</span><?php endif?></div><div><span class="badge <?=$item['sale']?'sold':''?>"><?=$item['sale']?'Solgt':'Til salgs'?></span><h2><?=money($item['price'])?></h2><p><?=e($item['seller'])?> · <?=e($item['rack'])?> · Str. <?=e($item['size'])?></p><div class="label"><svg class="barcode" data-code="<?=e($code)?>"></svg><strong><?=e($code)?></strong><p><?=e($item['name'])?> · <?=money($item['price'])?></p></div><?php if($isAdmin&&!$item['sale']):?><form method="post" onsubmit="return confirm('Bekreft at kunden har betalt <?=e(money($item['price']))?>?')"><?php action('sell');?><input type="hidden" name="item_id" value="<?=$item['id']?>"><button>Registrer som solgt →</button></form><p class="muted">Registrer salget etter at betaling er mottatt.</p><?php elseif($item['sale']):?><p>Solgt <?=e($item['sold_at'])?></p><?php endif?></div></section><?php endif?>
<?php elseif($page==='new'):$sellers=query('SELECT id,name FROM users ORDER BY name')->fetchAll();$racks=query('SELECT * FROM racks ORDER BY name')->fetchAll();?><p class="eyebrow">GI PLAGGET EN NY START</p><h1>Registrer et plagg</h1><form class="panel form-grid" method="post" enctype="multipart/form-data"><?php action('item');field('Hva slags plagg?','name','text','placeholder="F.eks. blå strikkegenser" maxlength="160"');field('Størrelse','size','text','placeholder="F.eks. M / 38" maxlength="30"');field('Pris i kroner','price','text','inputmode="decimal" placeholder="250,00"');if($isAdmin):?><label>Eier<select name="seller_id"><?php foreach($sellers as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach?></select></label><?php endif?><label>Stativ<select name="rack_id"><?php foreach($racks as $r):?><option value="<?=$r['id']?>"><?=e($r['name'])?></option><?php endforeach?></select></label><label>Bilde av plagget<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" capture="environment"><small>Ta bilde med mobilen, eller velg et bilde. Maks 8 MB.</small></label><button>Lagre og lag etikett →</button></form>
