<?php elseif($page==='sellers'&&$isAdmin):?><p class="eyebrow">MENNESKENE BAK PLAGGENE</p><h1>Selgere og stativer</h1><div class="two-col"><form method="post" class="panel"><h2>Ny selger</h2><?php action('seller');?><input type="hidden" name="return" value="sellers"><?php field('Navn','name');field('E-post','email','email');field('Midlertidig passord','password','password','minlength="12"');field('Selgerens andel i prosent','share','number','min="0" max="100" value="80"');?><button>Opprett selger</button></form><section class="panel"><h2>Stativer</h2><?php foreach(query('SELECT * FROM racks') as $r):?><p class="row"><?=e($r['name'])?></p><?php endforeach?><form method="post"><?php action('rack');?><input type="hidden" name="return" value="sellers"><?php field('Navn på nytt stativ','name');?><button class="secondary">Legg til stativ</button></form></section></div><section class="panel"><h2>Registrerte selgere</h2><?php foreach(query('SELECT name,email,share FROM users ORDER BY name') as $s):?><p class="row"><strong><?=e($s['name'])?></strong> <?=e($s['email'])?> <span><?=$s['share']?> % til selger</span></p><?php endforeach?></section>
<?php elseif($page==='settlement'):?><p class="eyebrow">RETT PLAGG. RETT EIER. RETT OPPGJØR.</p><h1>Oppgjør</h1><p class="muted">Fordelingen låses ved salg. Registrering her flytter ikke penger; gjennomfør betalingen via bank eller Vipps.</p><section class="panel"><?php $rows=query('SELECT u.id,u.name,COALESCE(SUM(s.seller_amount),0) earned,COALESCE(SUM(CASE WHEN s.payout_id IS NULL THEN s.seller_amount ELSE 0 END),0) pending FROM users u LEFT JOIN items i ON i.seller_id=u.id LEFT JOIN sales s ON s.item_id=i.id '.($isAdmin?'':'WHERE u.id='.(int)$me['id']).' GROUP BY u.id ORDER BY u.name')->fetchAll();foreach($rows as $r):?><div class="row"><div><strong><?=e($r['name'])?></strong><small>Opptjent: <?=money($r['earned'])?></small></div><strong><?=money($r['pending'])?> utestående</strong><?php if($isAdmin&&$r['pending']>0):?><form method="post" onsubmit="return confirm('Har du overført beløpet til selgeren?')"><?php action('payout');?><input type="hidden" name="seller_id" value="<?=$r['id']?>"><input type="hidden" name="return" value="settlement"><button>Marker utbetalt</button></form><?php endif?></div><?php endforeach?></section><h2>Utbetalingshistorikk</h2><section class="panel"><?php $history=query('SELECT p.*,u.name FROM payouts p JOIN users u ON u.id=p.seller_id '.($isAdmin?'':'WHERE u.id='.(int)$me['id']).' ORDER BY p.id DESC')->fetchAll();if(!$history)echo '<p class="muted">Ingen utbetalinger registrert ennå.</p>';foreach($history as $p):?><p class="row"><strong><?=e($p['name'])?></strong><span><?=money($p['amount'])?></span><span><?=e($p['created_at'])?></span></p><?php endforeach?></section>
<?php else:?><div class="heading"><div><p class="eyebrow">LITT MER GJENBRUK. LITT MINDRE KAOS.</p><h1>Plagg med en historie<span class="dot">.</span></h1><p class="muted">Her har hvert plagg sin plass — og sin eier.</p></div><a class="button" href="/?page=new">＋ Registrer plagg</a></div><div class="stats"><article><span>PLAGG I BUTIKKEN</span><strong><?=$stats['available']?></strong><small>klare for en ny garderobe</small></article><article><span>SOLGT FOR</span><strong><?=money($stats['sold'])?></strong><small>samlet salgsbeløp</small></article><article><span>TIL UTBETALING</span><strong><?=money($stats['pending'])?></strong><small>selgernes utestående andel</small></article></div><form class="filters" method="get"><input name="q" placeholder="Søk etter plagg, nummer eller selger …" value="<?=e($_GET['q']??'')?>"><select name="status"><option value="">Alle plagg</option><option value="available" <?=($_GET['status']??'')==='available'?'selected':''?>>Til salgs</option><option value="sold" <?=($_GET['status']??'')==='sold'?'selected':''?>>Solgt</option></select><button class="secondary">Søk</button></form><div class="cards"><?php
$sql="SELECT i.*,u.name seller,r.name rack,s.id sale FROM items i JOIN users u ON u.id=i.seller_id JOIN racks r ON r.id=i.rack_id LEFT JOIN sales s ON s.item_id=i.id WHERE $filter";$args=[];if(trim($_GET['q']??'')!==''){$q='%'.trim($_GET['q']).'%';$sql.=' AND (i.name LIKE ? OR u.name LIKE ? OR CAST(i.id AS TEXT) LIKE ?)';$args=[$q,$q,$q];}if(($_GET['status']??'')==='sold')$sql.=' AND s.id IS NOT NULL';if(($_GET['status']??'')==='available')$sql.=' AND s.id IS NULL';$items=query($sql.' ORDER BY i.id DESC',$args)->fetchAll();foreach($items as $i):?><a class="card" href="/?item=<?=$i['id']?>"><div class="card-image"><?php if($i['photo']):?><img src="/?photo=<?=$i['id']?>" alt="<?=e($i['name'])?>" loading="lazy"><?php else:?><span>Et nytt kapittel<br><b>starter her.</b></span><?php endif?><span class="badge <?=$i['sale']?'sold':''?>"><?=$i['sale']?'Solgt':'Til salgs'?></span></div><div class="card-body"><small>#<?=str_pad((string)$i['id'],6,'0',STR_PAD_LEFT)?> · <?=e($i['rack'])?></small><h3><?=e($i['name'])?></h3><div class="row"><span><?=e($i['seller'])?> · <?=e($i['size'])?></span><strong><?=money($i['price'])?></strong></div></div></a><?php endforeach;if(!$items):?><section class="empty"><h2>Plass til nye historier.</h2><p>Registrer det første plagget med bilde, pris og eier.</p><a class="button" href="/?page=new">Registrer et plagg →</a></section><?php endif?></div><?php endif?></main><?php endif?><script src="/app.js" defer></script></body></html>
